sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Get track length from the related tournament record, default to 185 if not found
    let trackLength = current.round_match.tournament.track.length;
    let TRACK_LENGTH = trackLength ? trackLength : 185; // Track length in inches

    // Define constants
    const SCALE_FACTOR = 64;  // Scale factor for 1:64 scale
    const SECONDS_PER_HOUR = 3600;
    const INCHES_PER_MILE = 63360;

    // Initialize speed variables
    let r1Speed = null;
    let r2Speed = null;

    // Calculate speed in mph for R1 if R1_Time exists
    if (current.r1_time) {
        r1Speed = (TRACK_LENGTH / current.r1_time) * (SECONDS_PER_HOUR / INCHES_PER_MILE) * SCALE_FACTOR;
        current.r1_speed = r1Speed.toFixed(2); // Store result in a field, e.g., r1_speed
    }

    // Calculate speed in mph for R2 if R2_Time exists
    if (current.r2_time) {
        r2Speed = (TRACK_LENGTH / current.r2_time) * (SECONDS_PER_HOUR / INCHES_PER_MILE) * SCALE_FACTOR;
        current.r2_speed = r2Speed.toFixed(2); // Store result in a field, e.g., r2_speed
    }

    // Concatenate the speed values into a display field, e.g., Speed_Display
    current.Speed_Display = "R1 Speed (1:1): " + (r1Speed ? r1Speed.toFixed(2) : "N/A") + " mph, " +
                            "R2 Speed (1:1): " + (r2Speed ? r2Speed.toFixed(2) : "N/A") + " mph";

})(current, previous);
